import{z as n,x as i,o as t,c,q as s,j as d,D as r,d as a,s as p,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"MapReduce","description":"","frontmatter":{"title":"MapReduce","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mapreduce.md","filePath":"cs/mapreduce.md","lastUpdated":1791413859000}'),B={name:"cs/mapreduce.md"};function u(m,e,A,h,D,f){const o=i("Mermaid");return t(),c("div",null,[e[2]||(e[2]=s('<h1 id="mapreduce" tabindex="-1">MapReduce <a class="header-anchor" href="#mapreduce" aria-label="Permalink to &quot;MapReduce&quot;">​</a></h1><div class="epigraph"><p>把批处理收成 map 与 reduce 两次用户函数，中间用按键分区的排序连接；容错靠再执行任务，不靠分布式共享内存。</p><footer>—— Dean and Ghemawat, MapReduce, OSDI 2004 / CACM 2008</footer></div><p><a href="/cs/lakehouse-table-format">上一课</a>给出可共享的表快照。缺口是<strong>如何在上千台机器上算</strong>：不是新 SQL，是把函数接到分区洗牌。本课钉 MapReduce；Spark DAG 下一课去掉强制的两阶段。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全表扫描 + 分组聚合：map 发射 <code>(k,v)</code>，shuffle 按 <code>k</code> 聚集，reduce 做合计。缺口是调度与容错：一台 map 挂了，只重跑该分片；reduce 读的是持久化的中间文件。没有这套模型，湖上的文件只是静态。与并行 DBMS：MR 当初用松 schema 与廉价硬件换计划质量。</p><p><span class="marginnote">数字实例：统计 1 TB 日志的词频，若 &quot;the&quot; 出现 1 亿次且没有 combiner，map 端要为它发 1 亿条 (&quot;the&quot;, 1)；在每台 map 机器先合并成 (&quot;the&quot;, 本机小计)，shuffle 流量立刻从 1 亿条缩到接近机器数条——combiner 省的是网络，不是逻辑。</span></p><p><span class="marginnote">GFS 提供分片与复制。combiner 是可选的本地预聚合。记录条数不是负载：倾斜键会把一个 reduce 打满。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>输入分片 → map → 溢写排序 → 按分区拷到 reduce → 归并 → 输出。推测执行对付拖后腿。与湖仓：输入可以是表快照的文件清单。计数、倒排、连接（map 端或 reduce 端）都是同一骨架上的程序。</p><p><span class="marginnote">直觉类比：MapReduce 像集体改考卷——先把卷子分成 100 叠（分片），100 位助教各判一叠并按学号尾数写标签（map），再按尾数寄给 10 位统计员（shuffle），每人只加总自己的尾数组（reduce）。中途谁病了，把他那叠重判一遍就行，别人照旧。</span></p>',10)),(t(),d(l,null,{default:r(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%88%86%E7%89%87%22%5D%20--%3E%20M%5B%22map%22%5D%0A%20%20M%20--%3E%20SH%5B%22shuffle%20%2F%20%E6%8E%92%E5%BA%8F%22%5D%0A%20%20SH%20--%3E%20R%5B%22reduce%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=E("h2",{id:"机制",tabindex:"-1"},[a("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=E("p",null,[a("确定性的纯 map/reduce 使再执行等价于第一次。副作用（写外部）会打破这点——后课恰好一次要处理 sink。shuffle 是全对全的带宽税，也是倾斜的放大器：一键一个 reduce 打满，与 "),E("a",{href:"/cs/grace-hash-join"},"Grace hash join"),a(" 的热键同构。combiner 在 map 端预聚合，像两阶段哈希聚合的 local agg。")],-1)),(t(),d(l,null,{default:r(()=>[p(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22Worker%20A%20%E6%89%A7%E8%A1%8C%E6%9F%90%20map%20%E5%88%86%E7%89%87%22%5D%20--%3E%20C%5B%22A%20%E5%AE%95%E6%9C%BA%2C%20%E5%BF%83%E8%B7%B3%E8%B6%85%E6%97%B6%22%5D%0A%20%20C%20--%3E%20M%5B%22Master%20%E6%8A%8A%E8%AF%A5%E5%88%86%E7%89%87%E9%87%8D%E6%96%B0%E6%B4%BE%E7%BB%99%20Worker%20B%22%5D%0A%20%20M%20--%3E%20B%5B%22B%20%E9%87%8D%E8%B7%91%E5%90%8C%E4%B8%80%E6%AE%B5%E8%BE%93%E5%85%A5%2C%20%E7%BB%93%E6%9E%9C%E4%B8%8E%E7%AC%AC%E4%B8%80%E6%AC%A1%E7%9B%B8%E5%90%8C%22%5D%0A%20%20B%20--%3E%20D%5B%22%E4%B8%AD%E9%97%B4%E7%BB%93%E6%9E%9C%E8%90%BD%E7%9B%98%2C%20%E4%BD%8D%E7%BD%AE%E4%B8%8A%E6%8A%A5%20Master%22%5D%0A%20%20D%20--%3E%20R%5B%22reduce%20%E6%8C%89%E4%B8%8A%E6%8A%A5%E4%BD%8D%E7%BD%AE%E8%AF%BB%E4%B8%AD%E9%97%B4%E6%96%87%E4%BB%B6%22%5D%0A%20%20D%20--%3E%20N%5B%22%E5%85%B6%E4%BD%99%E5%88%86%E7%89%87%E7%85%A7%E5%B8%B8%2C%20%E5%8F%AA%E9%87%8D%E8%B7%91%E6%8C%82%E6%8E%89%E7%9A%84%E9%82%A3%E7%89%87%22%5D%0A"})]),fallback:r(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=s('<p><span class="marginnote">为什么重要：再执行容错的前提是 map/reduce 纯函数——同样输入必得同样输出。谁在 map 里偷偷写外部系统，重跑就会重复扣款、重复发信；「恰好一次」语义要靠后课的 sink 规范兜住。常见误区则是以为机器越多越快：1 个热键占 90% 数据时，shuffle 会把 90% 压给一个 reduce，加机器救不了倾斜，得靠 combiner 或加盐拆键。</span></p><p>输出提交常用目录改名当原子，像切根。与并行数据库：MR 当初用松 schema 与廉价硬件换计划质量；SQL-on-Hadoop 后来把 GROUP BY 编译回同一骨架。推测执行对付拖后腿机器，不修复倾斜。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Hadoop 配置百科。下一课 DAG 允许多阶段与内存缓存，避免每次强制物化两跳。不把 MR 当流处理：窗口与 watermark 是后课。图迭代用多次作业很笨，那是 Spark 动机。</p><p>后课默认：批 shuffle 可理解成 MR；迭代与流水用 DAG。连接仍是 map-side 广播或 reduce-side 按键碰面。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MapReduce：分片函数 + 按键洗牌 + 再执行容错。</li><li>倾斜与 shuffle 是主要代价；combiner 减流量。</li><li>Spark 与 DAG 下一课。</li><li>出处：Dean and Ghemawat, MapReduce, OSDI 2004。</li></ul>',7))])}const M=n(B,[["render",u]]);export{C as __pageData,M as default};
